namespace ZteImeiStudio.Windows;

internal sealed record OperationHelpSection(string Title, string Body, string? Commands = null);
internal sealed record OperationHelpTopic(string Title, string AccessibleName, string Introduction,
    IReadOnlyList<OperationHelpSection> Sections);

/// <summary>
/// User-facing account of the implemented Windows workflows. Keep this aligned
/// with Core/OnboardingEngine.cs, Core/ImeiEngine*.cs and the pinned device payloads.
/// </summary>
internal static class OperationHelpContent
{
    public static OperationHelpTopic DiagnosticAdb { get; } = new(
        "ADB для диагностики", "Подробно о включении диагностического ADB",
        "Отдельная операция включает USB ADB для исследования прошивки, даже если SSH уже работает. Она не устанавливает агент, не создаёт ключи и не переустанавливает SSH. Нужны адрес модема, пароль штатного Web и USB-кабель с передачей данных. Перед запуском отключите интерактивный терминал.",
        [
            new("1. Проверка доступа и модема",
                "Проверяются локальные незавершённые операции, Web-идентичность и USB ADB. Если приложение подключено по SSH, CID, прошивка и IMEI дополнительно связывают этот SSH с Web и ADB. Уже работающий root ADB подтверждается дважды: USB, root, ARM64, CID, boot ID, IMEI и версии прошивки должны совпасть. В таком случае бэкап, переключение USB и перезагрузка не выполняются. После операции SSH проверяется заново; ADB не становится обычным каналом работы."),
            new("2. Последовательное включение",
                "В публичной сборке для расшифровки и проверки бэкапа B31 нужен Backup-key suffix вашей прошивки: введите его в скрытое поле. Он не встроен в приложение и не сохраняется. Уже работающий ADB, штатный USB debug и продолжение после отправленного восстановления или перезагрузки суффикса не требуют. Перед новым запросом сохраняется свежий бэкап настроек. Сначала проверяется штатная USB-команда set mode=debug; для ранней CN B01–B27 при недоступной интроспекции разрешён один известный запрос. Ожидание root ADB — до 90 секунд. Для изменения доступа на прошивках кроме точной B31 требуется галочка пропуска общей проверки; это не расширяет поддержку установщика и не разрешает восстановление B31 на другой прошивке.\n\nТолько на B31 проверенный бэкап расшифровывается и сравнивается: если строки включения нет, добавляется только она, архив проверяется и восстанавливается один раз. Если строка уже есть, а root ADB отсутствует, запрашивается одна штатная перезагрузка без восстановления бэкапа. После возможной перезагрузки до четырёх минут ожидается подтверждённый root ADB.",
                "zwrt_bsp.usb.set {\"mode\":\"debug\"}\nzwrt_mc.device.manager.device_reboot {\"moduleName\":\"web\"}"),
            new("3. Продолжение после обрыва",
                "Намерение сохраняется в adb-access-pending.json до отправки запроса. Копии и результат лежат в ADBAccessBackups/<UUID>. Повторный запуск продолжает проверку той же операции; отправленные переключение USB, восстановление или перезагрузка не повторяются. После запроса восстановления или перезагрузки повторная проверка ADB использует сохранённую идентичность и не требует работающего Web. Незавершённая подготовка блокирует эту операцию, а незавершённое включение ADB блокирует установки, запись IMEI и терминал до завершения проверки.")
        ]);

    public static OperationHelpTopic Preparation { get; } = new(
        "Как выполняется предварительная подготовка",
        "Подробно о предварительной подготовке модема",
        "Кнопка подготавливает доступ к модему через штатный Web, USB ADB и затем SSH. Она может восстановить изменённый бэкап настроек, чтобы включить ADB на проверенной B31, и установить агент с отдельным SSH-доступом. Открытие этой справки ничего не запускает.",
        [
            new("1. Начало подготовки: вход и резервная копия",
                "В публичной сборке для расшифровки и проверки бэкапа B31 нужен Backup-key suffix вашей прошивки: введите его в скрытое поле. Он не встроен в приложение и не сохраняется. Уже работающий ADB, штатный USB debug и продолжение после отправленного восстановления или перезагрузки суффикса не требуют. Нужны адрес модема, пароль штатного Web, отдельный пароль агента и USB-кабель с передачей данных. «Проверить подключения» только проверяет каналы, а «Подключиться» проверяет и подключает SSH. USB ADB используется для подготовки и диагностики. Включение ADB и установка выполняются отдельной кнопкой предварительной подготовки. Приложение берёт локальную блокировку и проверяет незавершённые операции.\n\nЧерез HTTP /ubus/ запрашивается zte_web_sault, вычисляется SHA-256 пароля и затем SHA-256 этого хэша вместе с challenge. В web_login передаётся полученный хэш. При неверном пароле подготовка останавливается; другие пароли автоматически не подбираются. Затем читаются IMEI, внешняя и внутренняя версии прошивки. Создаётся и скачивается свежий зашифрованный бэкап настроек. Идентичность проверяется ещё раз; оригинал, identity.json и SHA-256 сохраняются локально в SetupBackups/<UUID>. Это копия настроек, не полный образ памяти.\n\nДля проверки уже работающего ADB или SSH расшифровка архива не требуется. Backup-key suffix используется только в ветке восстановления B31. Пароли и веб-сессия в журнал этапов не записываются.",
                "POST http://<modem>/ubus/\nzwrt_web.web_login_info {}\nzwrt_web.web_login {\"password\":\"<challenge hash>\"}\nzwrt_web.device_info {}\nzwrt_mc.device.manager.device_backup_proc {\"procType\":\"web\"}\nGET http://<modem>/backup/back_parameter\nSetupBackups/<UUID>/back_parameter.original\nsetup-pending.json"),
            new("2. Если SSH или ADB уже работает",
                "Сначала проверяется существующая установка SSH и агента. Успех требует доверенного ключа сервера, root-доступа и совпадения идентичности модема. Если готовность подтверждена, подготовка завершается без повторного включения ADB или переустановки существующего агента. При продолжении ранее начатой установки дополнительно проверяется её журнал.\n\nЕсли готового SSH нет, встроенный adb выполняет devices -l. Учитываются состояния device, offline, unauthorized и отсутствие прав. Если USB-дескриптора usb: нет, что встречается в Windows, выполняется adb -d get-serialno: serial должен совпасть с единственным подтверждённым USB-устройством. Сетевой ADB и эмуляторы не принимаются за USB-модем. Затем через adb -s <serial> shell проверяются root, ARM64, CID, хэши прошивки и данные штатного Web. Совпадение с целевым модемом обязательно.\n\nПри готовом ADB способы его включения пропускаются. Программа переходит к проверке профиля установщика и установке SSH/агента. Отсутствие поля usb: или одного лишь SSH больше не служит причиной восстанавливать бэкап.",
                "adb devices -l\nadb -d get-serialno\nadb -s <serial> shell <identity-check>\nid -u\nuname -m\nsha256sum /firmware/image/modem.b16 /usr/bin/diag-router\ncat /sys/block/mmcblk0/device/cid\nubus call zwrt_web device_info '{}'"),
            new("3. Ранние прошивки: штатное переключение USB",
                "Для ранних прошивок сначала включите галочку «Не проверять прошивку»: обычный режим подготовки проверен на B31. Эта галочка не разрешает установку компонентов для неподдерживаемой прошивки. Если подходящий ADB не найден, приложение читает список методов zwrt_bsp.usb через JSON-RPC list. При объявленном set с параметром mode можно применить штатный способ. Если сам список недоступен, единственная резервная попытка разрешена только для известного исторического семейства CN MU5250 до B27 включительно. Если список явно не содержит set, метод пропускается. На неизвестной прошивке наличие одного похожего названия версии не разрешает восстановление B31.\n\nПеред изменением ещё раз сверяется Web-идентичность, а намерение сохраняется в setup-pending.json. Затем ровно один раз отправляется zwrt_bsp.usb.set {\"mode\":\"debug\"}. USB-сеть может исчезнуть при смене состава USB; подключение компьютера по Wi-Fi модема помогает сохранить Web. Этот способ сам по себе не загружает бэкап и не вызывает перезагрузку.\n\nПринятый запрос, отказ и неподтверждённый ответ различаются в журнале. До 90 секунд проверяется появление реального root USB ADB того же модема; ответ RPC 0 не считается готовностью. После обрыва эта команда автоматически не повторяется. Если ADB не появился, переход к восстановлению возможен только для B31 после повторного входа в Web, совпадения устройства и создания нового бэкапа. Если Web не вернулся, подготовка останавливается.",
                "POST /ubus/\n{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"list\",\"params\":[\"zwrt_bsp.usb\"]}\n# After login, one call:\nzwrt_bsp.usb.set {\"mode\":\"debug\"}\n# Repeated verification only:\nadb devices -l\nadb -s <serial> shell <identity-check>"),
            new("4. B31: включение через бэкап и перезагрузку",
                "Этот способ применяется только к проверенному профилю MU5250 B31, если работающий ADB не подтверждён. Свежий архив расшифровывается в памяти с использованием IMEI и Backup-key suffix. Проверяются OpenSSL Salted__, вложенные gzip/tar, MD5, имена файлов и метаданные. В etc/rc.local сразу после #!/bin/sh добавляется только приведённая ниже строка. Остальные записи сохраняются и сверяются с оригиналом. Результат заново упаковывается, шифруется и расшифровывается для контрольной проверки.\n\nПеред загрузкой сохраняется back_parameter.adb-only и повторно сверяется Web-устройство. CGI-загрузчик обязан подтвердить SHA-256 загруженных байт. Затем устройство сверяется ещё раз, в журнал записывается restore-requested и один раз вызывается device_restore_proc. Модем восстанавливает настройки и перезагружается; на это время связь прерывается. Программа ожидает USB ADB до четырёх минут и проверяет root и идентичность. Сам факт принятия восстановления не завершает подготовку.\n\nЕсли строка уже есть в исходном rc.local, архив повторно не восстанавливается: проверяется фактический ADB и показывается причина его отсутствия. Процесс adbd может быть запущен, когда USB всё ещё в обычном сетевом режиме; одного процесса недостаточно. При потерянном ответе restore повторный restore не отправляется. Продолжение использует сохранённый журнал и проверку устройства; уже отправленный установщик также не запускается заново вслепую.",
                "# Added inside the backup, executed at boot:\necho 1 > /sys/class/android_usb/android0/usb_op\nPOST http://<modem>/cgi-bin/cgi-upload\n  filename=/tmp/back_parameter\n  filedata=<verified encrypted backup>\nzwrt_mc.device.manager.device_restore_proc {\"procType\":\"web\"}\nSetupBackups/<UUID>/back_parameter.adb-only"),
            new("5. Ошибки подключения и границы поддержки",
                "«Не обнаружен»: проверьте USB-кабель данных и USB-порт; в Windows также драйвер Android ADB в диспетчере устройств. Кабель только для зарядки не подходит. «Unauthorized»: устройство обнаружено, но не разрешило отладку; подтвердите запрос на модеме, если он показан. «Offline»: транспорт найден, но shell не отвечает; переподключите кабель и повторите проверку. Отсутствие прав, отказ запуска локального adb и ошибка удалённой команды показываются отдельно. Программа не устанавливает драйвер и не отключает проверку подписи драйверов.\n\nЕсли USB ADB видит устройство, но оно не подтверждает root, архитектуру или идентичность нужного модема, успешное подключение не заявляется; в диагностике сохраняется причина. До передачи установщика все эти проверки должны пройти. При нескольких подходящих устройствах первый попавшийся serial не выбирается. Перед дальнейшей установкой требуются совпадающие IMEI/версии и CID, а каждый shell-вызов должен вернуть отдельный маркер удалённого кода завершения: локальный код adb 0 не скрывает ошибку команды на модеме.\n\nПолучение ADB и совместимость установщика проверяются отдельно. Для SSH/агента поддерживаются точные хэши B31 и экспериментальной B02. На ранней прошивке штатный способ может включить ADB, но установка неподдерживаемых компонентов будет остановлена с сообщением о неподдерживаемой прошивке или версии diag-router. Галочка пропуска общей проверки прошивки не снимает ограничения установщика. Восстановление B31 не применяется к B02 или неизвестной прошивке. Заводские пароли, fac_open и скрытые factory-методы автоматически не перебираются."),
            new("6. Передача и установка компонентов",
                "Перед установкой проверяются SHA-256 встроенных zte-agent, dropbear и сценариев, CID, свободное место, типы и права каталогов. При необходимости создаются /data/local и /data/local/tmp. В приватный /data/local/tmp/zte-imei-setup-<UUID> через adb push передаются агент, Dropbear, установщик, сценарий автозапуска, открытый SSH-ключ и сценарий запуска агента. Каждый incoming-файл сверяется по SHA-256 до переименования. До постоянных правок установщик сохраняет исходные файлы и их хэши в приватном журнале /data/local/tmp/zte-imei-installations/<UUID>.",
                "adb.exe -s <serial> push <файл> <stage>/incoming-<UUID>\nsha256sum <stage>/incoming-<UUID>\nsh <stage>/setup-agent.sh <stage> <CID> <SHA256-компонентов> <профиль>"),
            new("7. Какие файлы меняются на модеме",
                "Если агента ещё нет, он размещается в /data/zte-agent, а root-сценарий запуска с паролем агента — в /data/local/tmp/start_zte_agent.sh. Уже существующий агент и его пароль сохраняются. При необходимости Dropbear и dropbearkey размещаются в /data/bin; открытый ключ приложения добавляется в /etc/dropbear/authorized_keys без удаления других ключей. Серверные ключи хранятся в /etc/dropbear, их копии и authorized_keys — в /data/dropbear. В /etc/rc.local добавляется вызов /data/local/tmp/start_zte_imei_studio.sh: он запускает отсутствующий агент и отдельный SSH-слушатель на порту 2222 с входом по ключу. До правок установщик сохраняет прежние версии затронутых файлов в своём журнале.",
                "# Добавляемый автозапуск в /etc/rc.local:\nsh /data/local/tmp/start_zte_imei_studio.sh\n# Отдельный SSH-слушатель:\n/data/bin/dropbear -s -P /var/run/zte-imei-dropbear.pid -p 2222"),
            new("8. SSH-ключ и итоговая проверка",
                "Встроенный ssh-keygen.exe создаёт или повторно использует локальную пару Ed25519. Приватный ключ остаётся в %LOCALAPPDATA% с ограниченными Windows ACL; на модем передаётся только публичный. Серверный Ed25519 host key читается через проверенный ADB с повторной сверкой устройства и закрепляется в отдельном known_hosts. SSH-соединение устанавливает библиотека SSH.NET; ключ сервера сравнивается с закреплённым побайтно, без автоматического принятия нового ключа. После установки сверяются идентичности ADB и SSH, процесс агента и, для нового агента, вход заданным паролем. На B31 дополнительно читается пара NV и сравнивается с API; на B02 запись NV не выполняется. Только после проверок установщик получает --commit.",
                "# Локальные файлы Windows:\n%LOCALAPPDATA%\\ZTE IMEI Studio\\SSH\\id_ed25519\n%LOCALAPPDATA%\\ZTE IMEI Studio\\SSH\\id_ed25519.pub\n%LOCALAPPDATA%\\ZTE IMEI Studio\\SSH\\known_hosts\n# Host key читается через ADB:\n/data/bin/dropbearkey -y -f /etc/dropbear/dropbear_ed25519_host_key\nsh <stage>/setup-agent.sh --commit <журнал> <CID> <профиль>"),
            new("9. Если связь прервалась",
                "Локальный setup-pending.json хранит стадию и идентичность. Уже отправленное восстановление Web-бэкапа автоматически не повторяется. Если вызов установщика мог дойти до устройства, приложение сверяет удалённый журнал; автоматическое завершение возможно только из подтверждённых состояний ready или complete. Оригинальный архив сохраняется в SetupBackups/<UUID>; installation.log появляется после ответа установщика, setup-result.json — после успешного завершения. Временный локальный файл с паролем удаляется после передачи. Подготовка сама по себе не записывает новые IMEI, не устанавливает Launcher или русификацию и не прошивает raw-раздел ZTEDATA.",
                "%LOCALAPPDATA%\\ZTE IMEI Studio\\setup-pending.json\n%LOCALAPPDATA%\\ZTE IMEI Studio\\SetupBackups\\<UUID>\\installation.log\n%LOCALAPPDATA%\\ZTE IMEI Studio\\SetupBackups\\<UUID>\\setup-result.json")
        ]);

    public static OperationHelpTopic Imei { get; } = new(
        "Как записываются оба IMEI",
        "Подробно о записи обоих IMEI",
        "Кнопка меняет два индекса NV550 через проверенные помощники DIAG/EFS. До первой записи приложение сохраняет исходные NV и EFS config на Windows, временно разрешает запись и после двух перезагрузок подтверждает итог. Это операция только для проверенной MU5250 B31; экспериментальная B02 остаётся режимом чтения IMEI.",
        [
            new("1. Доступ и ограничения",
                "Запись запускается только после подключения root SSH; эта кнопка сама не выполняет предварительную подготовку. SSH.NET использует локальный Ed25519 private key и точный host key из known_hosts, полученный при подготовке. Оба новых IMEI должны состоять из 15 цифр, иметь правильную контрольную цифру и различаться. Перед записью снова требуются точные SHA-256 прошивки MU5250 B31 и diag-router: галочка пропуска общей проверки не снимает этот запрет. Незавершённая подготовка или операция IMEI блокирует новую запись.",
                "%LOCALAPPDATA%\\ZTE IMEI Studio\\SSH\\id_ed25519\n%LOCALAPPDATA%\\ZTE IMEI Studio\\SSH\\known_hosts\nsha256sum /firmware/image/modem.b16 /usr/bin/diag-router"),
            new("2. Исходные данные и блокировки",
                "Приложение сверяет eMMC CID, хэши прошивки и boot_id. Оно берёт локальную imei-operation.lock, сохраняет токен в imei-lock.json и создаёт принадлежащую операции /tmp/zte-imei-app.lock на модеме. Помощник zte_nv читает оба 128-байтных индекса NV550; значения IMEI сравниваются с get_imei и get_imei2 штатного ubus API. Если предложенная пара уже записана, операция не начинается.",
                "cat /sys/block/mmcblk0/device/cid /proc/sys/kernel/random/boot_id\n<zte_nv> --snapshot\nubus call zwrt_zte_mdm.api get_imei\nubus call zwrt_zte_mdm.api get_imei2\n%LOCALAPPDATA%\\ZTE IMEI Studio\\imei-lock.json\n/tmp/zte-imei-app.lock"),
            new("3. Проверенные временные помощники",
                "Перед каждым вызовом встроенные zte_nv, zte_config и zte_config_read сверяются с Resources/Helpers/helpers.json. В приватный /tmp/zte-imei-<UUID> помощник передаётся по stdin SSH, получает права 700 и снова проверяется по SHA-256. Если нужен план, он передаётся отдельно и проверяется таким же образом. После вызова приложение пытается удалить только свой временный каталог. Эти помощники используют DIAG/EFS и не получают произвольные команды записи.",
